// Extract crosslink data from WF-02's POST body
// Canal de destino: el channel_id del evento de origen. Si no hay, SOLO el canal
// configurado aqui. Nunca hay canal por defecto: sin canal no se publica.
const CONFIGURED_CHANNEL = '';
const body = $input.item.json.body || $input.item.json;

const entryId = body.entry_id;
const fileName = body.file_name;
const relatedIds = body.related_ids || [];
const relatedCount = body.related_count || relatedIds.length;
const tags = body.tags || [];
const entities = body.entities || [];
const summary = body.summary || '';
const channelId = body.channel_id || CONFIGURED_CHANNEL;

if (!entryId) {
  throw new Error('No entry_id in payload');
}

return {
  json: {
    entry_id: entryId,
    file_name: fileName,
    channel_id: channelId,
    related_ids: relatedIds,
    related_count: relatedCount,
    tags: tags,
    entities: entities,
    summary: summary
  }
};

const prev = $('Parse Payload').first().json;
const hasRelated = prev.related_ids && prev.related_ids.length > 0;
const related = hasRelated
  ? $input.all().map(i => i.json).filter(e => e && e.file_name)
  : [];
return [{ json: { ...prev, related_entries: related } }];

// Build a Slack notification message
const data = $input.item.json;
const relatedEntries = data.related_entries || [];
const count = data.related_count;
const fileName = data.file_name || 'unknown';
const tags = data.tags || [];
const entities = data.entities || [];
const summary = data.summary || '';

// Build the matched entries list (top 10)
const entryLines = relatedEntries.slice(0, 10).map((e, i) => {
  const eTags = (e.tags || []).slice(0, 3).join(', ');
  const shortSummary = (e.summary || '').substring(0, 80);
  return `${i + 1}. *${e.file_name}* — _${shortSummary}${shortSummary.length >= 80 ? '...' : ''}_ [${eTags}]`;
}).join('\n');

const moreText = relatedEntries.length > 10 ? `\n_...y ${relatedEntries.length - 10} mas_` : '';

const message = `:link: *Crosslink Alert: ${count} conexiones encontradas*\n\n` +
  `*Entrada nueva:* \`${fileName}\`\n` +
  (summary ? `*Resumen:* ${summary}\n` : '') +
  `*Tags:* ${tags.join(', ')}\n` +
  `*Entidades:* ${entities.join(', ')}\n\n` +
  `*Entradas relacionadas:*\n${entryLines}${moreText}\n\n` +
  `_La espiral conecta ${count} nodos._`;

return {
  json: {
    slack_message: message,
    channel_id: data.channel_id,
    file_name: fileName,
    entry_id: data.entry_id,
    related_count: count
  }
};

// Proteccion frente a duplicados en n8n (cubre llamadas directas): un aviso por entry_id.
const sd = $getWorkflowStaticData('global');
sd.notified = sd.notified || {};
const item = $input.item.json;
const key = String(item.entry_id);
const prev = sd.notified[key];
const now = Date.now();
if (prev && (prev.state === 'done' || (prev.state === 'inflight' && now - prev.at < 300000))) {
  return { json: { ...item, duplicate: true } };
}
sd.notified[key] = { state: 'inflight', at: now };
return { json: { ...item, duplicate: false } };

// Cada llamada a Slack debe devolver ok:true. Si no, se libera la reserva (para permitir
// reintento) y el nodo siguiente hace fallar la ejecucion.
const r = $input.item.json;
const sd = $getWorkflowStaticData('global');
sd.notified = sd.notified || {};
const built = $('Build Slack Message').item.json;
const key = String(built.entry_id);
if (r.ok !== true) {
  delete sd.notified[key];
  return { json: { slack_failed: true, slack_error: r.error || 'respuesta sin ok:true' } };
}
sd.notified[key] = { state: 'done', at: Date.now() };
return { json: { ...r, entry_id: built.entry_id, file_name: built.file_name, channel_id: built.channel_id } };

const r = $input.item.json;
if (r.slack_failed) {
  throw new Error('Slack rechazo el mensaje: ' + r.slack_error);
}
return { json: r };
